      NEW_BUDGET: '新增预算', TRANSFER_SAME_DEPT: '同部门调拨', TRANSFER_CROSS_DEPT: '跨部门调拨', REDUCE: '追减',
      FULL: '全额结转', PERCENT: '比例结转', EXPIRE: '过期清零', IN: '调入', OUT: '调出',
